  /** A parked ambulance at the hospital entrance: street furniture, not a wall. */
  _ambulance(x, z) {
    const amb = new THREE.Group();
    const body = new THREE.Mesh(BOX, new THREE.MeshLambertMaterial({ color: 0xf4f6f8 }));
    body.scale.set(2.1, 1.3, 4.6);
    body.position.y = 1.05;
    body.castShadow = true;
    amb.add(body);
    const cab = new THREE.Mesh(BOX, new THREE.MeshLambertMaterial({ color: 0xdfe4e8 }));
    cab.scale.set(2.0, 0.8, 1.2);
    cab.position.set(0, 0.85, -2.6);
    amb.add(cab);
    const crossMat = new THREE.MeshBasicMaterial({ color: 0xe03a3a });
    const tyreMat = new THREE.MeshLambertMaterial({ color: 0x0c0d0f });
    const hubMat = new THREE.MeshLambertMaterial({ color: 0xcfd4da });
    for (const s of [-1, 1]) {
      const ch = new THREE.Mesh(BOX, crossMat);
      ch.scale.set(0.7, 0.22, 0.06);
      ch.position.set(s * 1.06, 1.4, 0.4);
      amb.add(ch);
      const cv = new THREE.Mesh(BOX, crossMat);
      cv.scale.set(0.22, 0.7, 0.06);
      cv.position.set(s * 1.06, 1.4, 0.4);
      amb.add(cv);
      for (const zz of [-1.4, 1.4]) {
        const wheel = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.34, 0.24, 14), tyreMat);
        wheel.rotation.z = Math.PI / 2;
        wheel.position.set(s * 1.02, 0.34, zz);
        amb.add(wheel);
        const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.16, 0.26, 10), hubMat);
        hub.rotation.z = Math.PI / 2;
        hub.position.set(s * 1.02, 0.34, zz);
        amb.add(hub);
      }
    }
    amb.position.set(x, 0, z);
    amb.rotation.y = 0.2;
    this.scene.add(amb);
    this._solid(x, z, 2.4, 1.2, 2.2);
  }

