  // ---- the cargo port ------------------------------------------------------
  _buildPort() {
    const px = -CITY_HALF - 70;
    const pz = -60;
    const yard = new THREE.Mesh(
      new THREE.PlaneGeometry(150, 190),
      new THREE.MeshLambertMaterial({ color: 0x9aa0a4 }));
    yard.rotation.x = -Math.PI / 2;
    yard.position.set(px, 0.03, pz);
    yard.receiveShadow = true;
    this.scene.add(yard);

    const contMats = CONTAINER_HUES.map((h) => new THREE.MeshLambertMaterial({ map: containerTexture(h) }));
    const rnd = mulberry32(2024);
    for (let i = 0; i < 26; i++) {
      const cx = px - 60 + rnd() * 120;
      const cz = pz - 80 + rnd() * 160;
      const stack = 1 + Math.floor(rnd() * 3);
      for (let s = 0; s < stack; s++) {
        const c = new THREE.Mesh(BOX, contMats[Math.floor(rnd() * contMats.length)]);
        c.scale.set(6.1, 2.6, 2.5);
        c.position.set(cx + (rnd() - 0.5) * 0.4, 1.3 + s * 2.65, cz);
        c.rotation.y = (rnd() - 0.5) * 0.12;
        c.castShadow = true;
        c.receiveShadow = true;
        this.scene.add(c);
      }
      this._solid(cx, cz, 3.2, 1.5, 2.6 * stack);
    }

    // Two gantry cranes: portal legs, a beam and a cab.
    const craneMat = new THREE.MeshLambertMaterial({ color: 0xe0a52a });
    for (const dz of [-40, 40]) {
      const crane = new THREE.Group();
      for (const s of [-1, 1]) {
        const leg = new THREE.Mesh(BOX, craneMat);
        leg.scale.set(1.6, 26, 1.6);
        leg.position.set(s * 14, 13, 0);
        leg.castShadow = true;
        crane.add(leg);
        this._solid(px + s * 14, pz + dz, 1, 1, 26);
      }
      const beam = new THREE.Mesh(BOX, craneMat);
      beam.scale.set(34, 2.2, 2.4);
      beam.position.set(0, 26, 0);
      beam.castShadow = true;
      crane.add(beam);
      const cab = new THREE.Mesh(BOX, new THREE.MeshLambertMaterial({ color: 0x30414f }));
      cab.scale.set(3, 2.6, 3);
      cab.position.set(4, 23.4, 0);
      crane.add(cab);
      crane.position.set(px, 0, pz + dz);
      this.scene.add(crane);
    }

    // Quay wall and a couple of cargo ships offshore.
    const quay = new THREE.Mesh(BOX, new THREE.MeshLambertMaterial({ color: 0x6d7276 }));
    quay.scale.set(150, 3, 8);
    quay.position.set(px, 1.5, pz + 100);
    this.scene.add(quay);
    for (const [ox, oz] of [[-40, 150], [30, 175]]) {
      const hull = new THREE.Mesh(BOX, new THREE.MeshLambertMaterial({ color: 0x24384a }));
      hull.scale.set(14, 4, 42);
      hull.position.set(px + ox, 0.5, pz + oz);
      this.scene.add(hull);
      const deck = new THREE.Mesh(BOX, new THREE.MeshLambertMaterial({ color: 0x8a9298 }));
      deck.scale.set(12, 5, 8);
      deck.position.set(px + ox, 5.5, pz + oz - 14);
      this.scene.add(deck);
    }
  }

