  // ---- pier, lighthouse, umbrellas, lifeguard, boats ------------------------
  _buildCoast() {
    const postMat = new THREE.MeshLambertMaterial({ color: 0x5d452b });
    const timberMat = new THREE.MeshLambertMaterial({ color: 0x8a6a45 });
    const px = 56;
    const pz = COAST_Z + 60;

    // Fishing pier reaching into the surf.
    const deck = new THREE.Mesh(BOX, timberMat);
    deck.scale.set(10, 0.7, 74);
    deck.position.set(px, 0.9, pz);
    deck.castShadow = true;
    deck.receiveShadow = true;
    this.scene.add(deck);
    for (let i = 0; i < 10; i++) {
      for (const s of [-1, 1]) {
        const post = new THREE.Mesh(CYL, postMat);
        post.scale.set(0.32, 2.6, 0.32);
        post.position.set(px + s * 4.6, -0.3, pz - 34 + i * 7.6);
        this.scene.add(post);
      }
    }
    for (const s of [-1, 1]) {
      const rail = new THREE.Mesh(BOX, timberMat);
      rail.scale.set(0.22, 0.9, 74);
      rail.position.set(px + s * 4.9, 2.0, pz);
      this.scene.add(rail);
    }
    this._solid(px, pz + 34, 5, 3, 1.2);

    // Lighthouse with a sweeping beam.
    const lx = 150;
    const lz = COAST_Z + 6;
    const towerMat = new THREE.MeshLambertMaterial({ color: 0xf2f2ea });
    const bandMat = new THREE.MeshLambertMaterial({ color: 0xd23b2e });
    const tower = new THREE.Mesh(CYL, towerMat);
    tower.scale.set(4.2, 22, 4.2);
    tower.position.set(lx, 11, lz);
    tower.castShadow = true;
    this.scene.add(tower);
    for (const [y, r] of [[5.5, 4.4], [11.5, 4.15]]) {
      const band = new THREE.Mesh(CYL, bandMat);
      band.scale.set(r, 1.4, r);
      band.position.set(lx, y, lz);
      this.scene.add(band);
    }
    const lampRoom = new THREE.Mesh(CYL, new THREE.MeshLambertMaterial({ color: 0x2b3440 }));
    lampRoom.scale.set(3.0, 3.0, 3.0);
    lampRoom.position.set(lx, 23.4, lz);
    this.scene.add(lampRoom);
    const cap = new THREE.Mesh(new THREE.ConeGeometry(3.4, 3.2, 12), bandMat);
    cap.position.set(lx, 26.4, lz);
    this.scene.add(cap);
    this._solid(lx, lz, 4.4, 4.4, 22);
    const beamGroup = new THREE.Group();
    beamGroup.position.set(lx, 23.4, lz);
    const beam = new THREE.Mesh(
      new THREE.ConeGeometry(4.5, 70, 16, 1, true),
      new THREE.MeshBasicMaterial({
        color: 0xfff3b0, transparent: true, opacity: 0.055, fog: false,
        blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
      }));
    beam.rotation.z = Math.PI / 2;
    beam.position.set(35, 0, 0);
